/* 影子线 · 画面层
 * 一句歌词一张「卡」：每句配一张自己画的图，换句即切图。全部实时 Canvas 2D。
 * 坐标：以画面中心 (0,0) 为原点，逻辑宽 1000 × 高 560（mv.js 负责缩放与运镜）。
 * 词汇：经纬网、地球仪、日影/木杆、钟、海岸线、分规、山脊、火山、月食、晨昏线。
 */
'use strict';

const C = {
  ink: '#05080d',
  cyan: '#78e0d4', cyanHi: '#d2fff8', cyanDim: '#3c8d8a',
  amber: '#f0c078', amberHi: '#ffe2ae', amberDim: '#9c6c34',
  ivory: '#f4ecdc', ivory2: '#dcd2be',
  purple: '#b08ad0', red: '#e0715a', blue: '#9fb8f0', sea: '#2a6d78',
  paper: '#e9dfc9', paperDk: '#bfb298', night: 'rgba(3,6,10,0.80)',
  dim: 'rgba(200,230,226,0.40)', dimW: 'rgba(240,200,140,0.42)',
};

let T_CUR = 2.4; // 当前场景时长，mv.js 每帧写入
const E = (e, d, dur) => smooth(clamp((e - (d || 0)) / Math.min(dur || 0.5, Math.max(0.18, T_CUR * 0.42))));

/* ---------------------------------------------------------------- 笔 */
function ln(g, pts, o = {}) { glowLine(g, pts, Object.assign({ w: 2.4, color: C.cyan, glow: 15 }, o)); }
function lnw(g, pts, o = {}) { glowLine(g, pts, Object.assign({ w: 2.6, color: C.amber, glow: 16 }, o)); }
function ci(g, x, y, r, o = {}) { glowCircle(g, x, y, r, Object.assign({ w: 2.2, color: C.cyan, glow: 15 }, o)); }
function ciw(g, x, y, r, o = {}) { glowCircle(g, x, y, r, Object.assign({ w: 2.6, color: C.amber, glow: 16 }, o)); }
function ar(g, x, y, r, a0, a1, o = {}) {
  if (a1 - a0 >= Math.PI * 2 - 1e-4) a1 = a0 + Math.PI * 2 - 0.001; // Skia 整圆 bug
  glowCircle(g, x, y, r, Object.assign({ a0, a1, w: 2.2, color: C.cyan, glow: 15 }, o));
}
function dt(g, x, y, r, o = {}) { glowDot(g, x, y, r, o); }
function tx(g, s, x, y, size, o = {}) {
  text(g, s, x, y, Object.assign({ size, weight: 600, font: FONT_SERIF, color: C.ivory, glow: 10 }, o));
}
function cnT(g, s, x, y, size, o = {}) {
  text(g, s, x, y, Object.assign({ size, weight: 700, font: FONT_SERIF_CN, color: C.ivory, glow: 10 }, o));
}
function cap(g, s, x, y, o = {}) {
  caps(g, s, x, y, Object.assign({ size: 12, ls: 3.2, color: C.dim }, o));
}
function num(g, s, x, y, size, o = {}) {
  text(g, s, x, y, Object.assign({ size, weight: 400, font: FONT_SERIF, color: C.amberHi, glow: 14, glowColor: '#ffc478', italic: true }, o));
}
// 细虚线（辅助线）
function dash(g, pts, o = {}) {
  const { color = 'rgba(150,220,214,0.42)', w = 1.2, da = [5, 7], a = 1 } = o;
  g.save(); g.globalAlpha = a; g.strokeStyle = color; g.lineWidth = w; g.setLineDash(da);
  g.beginPath(); pts.forEach((p, i) => i ? g.lineTo(p[0], p[1]) : g.moveTo(p[0], p[1])); g.stroke();
  g.restore();
}
function arrow(g, x1, y1, x2, y2, o = {}) {
  const { color = C.cyan, w = 2, head = 11, a = 1 } = o;
  const ang = Math.atan2(y2 - y1, x2 - x1);
  g.save(); g.globalAlpha = a;
  g.strokeStyle = color; g.lineWidth = w; g.shadowColor = color; g.shadowBlur = 10;
  g.beginPath(); g.moveTo(x1, y1); g.lineTo(x2, y2); g.stroke();
  g.beginPath(); g.moveTo(x2, y2);
  g.lineTo(x2 - head * Math.cos(ang - 0.42), y2 - head * Math.sin(ang - 0.42));
  g.lineTo(x2 - head * Math.cos(ang + 0.42), y2 - head * Math.sin(ang + 0.42));
  g.closePath(); g.fillStyle = color; g.fill();
  g.restore();
}


