const LANDS = LAND_RINGS; // 兼容旧名

// 正射投影：返回相机坐标 [X,Y,Z]，X/Y 已除 R，Z>0 表示朝向观众
function proj3(lat, lon, lon0, lat0) {
  const f = lat * Math.PI / 180, l = (lon - lon0) * Math.PI / 180, f0 = (lat0 || 0) * Math.PI / 180;
  const cf = Math.cos(f), sf = Math.sin(f), cl = Math.cos(l), sl = Math.sin(l);
  const cf0 = Math.cos(f0), sf0 = Math.sin(f0);
  return [cf * sl, -(cf0 * sf - sf0 * cf * cl), cf * cl * cf0 + sf * sf0];
}
// 兼容旧调用：返回 [X,Y,front]
function projLL(lat, lon, lon0, lat0) {
  const p = proj3(lat, lon, lon0, lat0);
  return [p[0], p[1], p[2] > 0];
}
// 把 [纬度,经度] 环裁到可见半球（Sutherland-Hodgman，交点在球面地平圈上），返回 [X,Y] 环
function clipRingLL(ring, lon0, lat0) {
  const n = ring.length;
  if (n < 4) return [];
  const p = ring.map(([la, lo]) => proj3(la, lo, lon0, lat0));
  const out = [];
  for (let i = 0; i < n; i++) {
    const a = p[i], b = p[(i + 1) % n];
    const ain = a[2] >= 0, bin = b[2] >= 0;
    if (ain) out.push([a[0], a[1]]);
    if (ain !== bin) {
      const t = a[2] / (a[2] - b[2]);
      let x = a[0] + (b[0] - a[0]) * t, y = a[1] + (b[1] - a[1]) * t;
      const L = Math.hypot(x, y) || 1;
      out.push([x / L, y / L]);   // 交点落到地平圈，避免弦切进圆盘
    }
  }
  return out;
}
// 把 [纬度,经度] 折线裁到可见半球：在地平圈断开，跨背面不再拉弦
function clipLineLL(line, lon0, lat0) {
  // 每段加密 3 个点，贴地平圈时不会画成折线
  const src = [];
  for (let i = 0; i < line.length - 1; i++) {
    let lo2 = line[i + 1][1];
    const lo1 = line[i][1];
    if (lo2 - lo1 > 180) lo2 -= 360;        // 跨 ±180 时按短弧插值
    else if (lo1 - lo2 > 180) lo2 += 360;
    for (let k = 0; k < 3; k++) {
      const u = k / 3;
      src.push([lerp(line[i][0], line[i + 1][0], u), lerp(lo1, lo2, u), i / (line.length - 1)]);
    }
  }
  src.push([line[line.length - 1][0], line[line.length - 1][1], 1]);
  const ps = src.map(([la, lo]) => proj3(la, lo, lon0, lat0));
  const seam = (a, b) => {
    const t = a[2] / (a[2] - b[2]);
    let x = a[0] + (b[0] - a[0]) * t, y = a[1] + (b[1] - a[1]) * t;
    const L = Math.hypot(x, y) || 1;
    return [x / L, y / L, 0];
  };
  const out = [];
  let cur = [], s0 = 0, s1 = 0;
  for (let i = 0; i < ps.length; i++) {
    const p = ps[i], vis = p[2] >= 0;
    if (i === 0) { if (vis) { cur = [p]; s0 = 0; s1 = 0; } continue; }
    const q = ps[i - 1], qvis = q[2] >= 0;
    if (vis && qvis) { cur.push(p); s1 = src[i][2]; }
    else if (vis) { cur = [seam(q, p), p]; s0 = src[i - 1][2]; s1 = src[i][2]; }
    else if (qvis) {
      cur.push(seam(q, p)); s1 = src[i][2];
      if (cur.length > 1) out.push({ pts: cur.map(v => [v[0], v[1]]), f0: s0, f1: s1 });
      cur = [];
    }
  }
  if (cur.length > 1) out.push({ pts: cur.map(v => [v[0], v[1]]), f0: s0, f1: s1 });
  return out;
}
// 球面经纬网：经线 30° 一条（椭圆），纬线 15° 一条（直线，间距 sinφ）
function globeGrid(g, cx, cy, R, lon0, o = {}) {
  const { col = 'rgba(150,226,218,0.26)', lw = 1, a = 1, lat0 = 0 } = o;
  g.save(); g.globalAlpha = a; g.strokeStyle = col; g.lineWidth = lw;
  for (let lon = -180; lon < 180; lon += 30) {
    const lam = (lon - lon0) * Math.PI / 180;
    const rx = Math.abs(Math.sin(lam)) * R;
    if (rx < 0.8) { g.beginPath(); g.moveTo(cx, cy - R); g.lineTo(cx, cy + R); g.stroke(); continue; }
    g.beginPath(); g.ellipse(cx, cy, rx, R, 0, 0, 6.2832); g.stroke();
  }
  for (let lat = -75; lat <= 75; lat += 15) {
    const f = lat * Math.PI / 180;
    if (lat0) { // 倾斜视角下纬线仍是椭圆，这里只支持赤道视角
      continue;
    }
    const y = cy - Math.sin(f) * R, hw = Math.cos(f) * R;
    g.beginPath(); g.moveTo(cx - hw, y); g.lineTo(cx + hw, y); g.stroke();
  }
  g.restore();
}
function drawGlobeLands(g, cx, cy, R, lon0, o = {}) {
  const { a = 1, fill = 'rgba(96,186,176,0.28)', line = 'rgba(170,240,230,0.70)', lw = 1, lat0 = 0 } = o;
  g.save(); g.beginPath(); g.arc(cx, cy, R, 0, 6.2832); g.clip();
  for (const ring of LANDS) {
    const pts = clipRingLL(ring, lon0, lat0);
    if (pts.length < 3) continue;
    g.globalAlpha = a; g.beginPath();
    for (let i = 0; i < pts.length; i++) {
      const x = cx + pts[i][0] * R, y = cy + pts[i][1] * R;
      i ? g.lineTo(x, y) : g.moveTo(x, y);
    }
    g.closePath();
    g.fillStyle = fill; g.fill();
    g.strokeStyle = line; g.lineWidth = lw; g.stroke();
  }
  g.restore();
}

// 夜半球：把球面按太阳方向切成昼夜（晨昏线是过球心的直线，正射视角下正确）
function nightCap(g, cx, cy, R, ang, night) {
  if (night <= 0) return;
  g.save();
  g.beginPath(); g.arc(cx, cy, R, 0, 6.2832); g.clip();
  g.translate(cx, cy); g.rotate(ang);
  g.fillStyle = `rgba(3,7,11,${0.82 * night})`;
  g.fillRect(0, -R, R * 1.02, R * 2);
  g.globalCompositeOperation = 'lighter';
  g.shadowColor = 'rgba(255,190,120,0.9)'; g.shadowBlur = 22;
  g.strokeStyle = 'rgba(255,214,160,0.75)'; g.lineWidth = 1.8;
  g.beginPath(); g.moveTo(0, -R); g.lineTo(0, R); g.stroke();
  g.restore();
}
/* ---------------------------------------------------------------- 图形积木 */

// 按长度比例截取折线
function partial(pts, f) {
  if (f <= 0) return [];
  let len = 0; const seg = [];
  for (let i = 1; i < pts.length; i++) {
    const d = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);
    seg.push(d); len += d;
  }
  const target = len * clamp(f, 0, 1);
  const out = [pts[0]];
  let acc = 0;
  for (let i = 1; i < pts.length; i++) {
    if (acc + seg[i - 1] <= target) { out.push(pts[i]); acc += seg[i - 1]; continue; }
    const k = (target - acc) / (seg[i - 1] || 1);
    out.push([pts[i - 1][0] + (pts[i][0] - pts[i - 1][0]) * k, pts[i - 1][1] + (pts[i][1] - pts[i - 1][1]) * k]);
    break;
  }
  return out;
}
function ptAt(pts, f) {
  let len = 0; const seg = [];
  for (let i = 1; i < pts.length; i++) { const d = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]); seg.push(d); len += d; }
  let target = len * clamp(f, 0, 1), acc = 0;
  for (let i = 1; i < pts.length; i++) {
    if (acc + seg[i - 1] < target) { acc += seg[i - 1]; continue; }
    const k = (target - acc) / (seg[i - 1] || 1);
    return [pts[i - 1][0] + (pts[i][0] - pts[i - 1][0]) * k, pts[i - 1][1] + (pts[i][1] - pts[i - 1][1]) * k];
  }
  return pts[pts.length - 1];
}

// 网格（画面局部用）
function grat(g, x, y, w, h, o = {}) {
  const { sx = 80, sy = 64, color = 'rgba(140,214,208,0.13)', w2 = 1, alpha = 1, cx = 0, cy = 0 } = o;
  g.save(); g.globalAlpha = alpha; g.strokeStyle = color; g.lineWidth = w2;
  for (let i = x; i <= x + w + 0.1; i += sx) { g.beginPath(); g.moveTo(i, y); g.lineTo(i, y + h); g.stroke(); }
  for (let j = y; j <= y + h + 0.1; j += sy) { g.beginPath(); g.moveTo(x, j); g.lineTo(x + w, j); g.stroke(); }
  if (cx || cy) {
    g.strokeStyle = 'rgba(240,200,140,0.20)'; g.lineWidth = 1.4;
    g.beginPath(); g.moveTo(cx, y); g.lineTo(cx, y + h); g.stroke();
    g.beginPath(); g.moveTo(x, cy); g.lineTo(x + w, cy); g.stroke();
  }
  g.restore();
}
// 地平线
function horizon(g, y, o = {}) {
  const { w = 1000, color = 'rgba(226,236,232,0.55)', warm = 0, alpha = 1 } = o;
  g.save();
  if (warm) {
    const gr = g.createLinearGradient(0, y - 150, 0, y + 4);
    gr.addColorStop(0, 'rgba(240,170,90,0)');
    gr.addColorStop(1, `rgba(240,170,90,${0.20 * warm})`);
    g.fillStyle = gr; g.fillRect(-w / 2, y - 150, w, 154);
  }
  g.globalAlpha = alpha; g.strokeStyle = color; g.lineWidth = 1.6;
  g.shadowColor = 'rgba(220,240,235,0.8)'; g.shadowBlur = 10;
  g.beginPath(); g.moveTo(-w / 2, y); g.lineTo(w / 2, y); g.stroke();
  g.shadowBlur = 0;
  g.strokeStyle = 'rgba(180,220,214,0.10)'; g.lineWidth = 1;
  for (let x = -w / 2; x <= w / 2; x += 20) {
    const l = ((x / 20) | 0) % 5 === 0 ? 9 : 4;
    g.beginPath(); g.moveTo(x, y); g.lineTo(x, y + l); g.stroke();
  }
  g.restore();
}
// 太阳
function sun(g, cx, cy, r, o = {}) {
  const { a = 1, rays = 0, col = '255,214,150' } = o;
  g.save(); g.globalAlpha = a; g.globalCompositeOperation = 'lighter';
  const gr = g.createRadialGradient(cx, cy, 0, cx, cy, r * 2.6);
  gr.addColorStop(0, `rgba(255,252,240,${0.95 * a})`);
  gr.addColorStop(0.22, `rgba(${col},0.85)`);
  gr.addColorStop(0.55, `rgba(${col},0.16)`);
  gr.addColorStop(1, `rgba(${col},0)`);
  g.fillStyle = gr; g.beginPath(); g.arc(cx, cy, r * 2.6, 0, 6.2832); g.fill();
  g.fillStyle = `rgba(255,250,236,${0.95 * a})`;
  g.beginPath(); g.arc(cx, cy, r * 0.62, 0, 6.2832); g.fill();
  if (rays) {
    g.strokeStyle = `rgba(${col},0.42)`; g.lineWidth = 1.2;
    for (let i = 0; i < rays; i++) {
      const ang = i / rays * 6.2832 + 0.2;
      g.beginPath();
      g.moveTo(cx + Math.cos(ang) * r * 1.15, cy + Math.sin(ang) * r * 1.15);
      g.lineTo(cx + Math.cos(ang) * r * (1.55 + 0.25 * Math.sin(i * 2.1)), cy + Math.sin(ang) * r * (1.55 + 0.25 * Math.sin(i * 2.1)));
      g.stroke();
    }
  }
  g.restore();
}
// 地球仪：经线/纬线/夜半球/晨昏线
function globe(g, cx, cy, r, o = {}) {
  const {
    a = 1, spin = 0, mer = 6, par = 5, night = 0, nightAng = 0.35, alpha = 1, lon0 = null,
    col = C.cyan, glow = 18, wire = true, term = true, fill = 'rgba(18,42,48,0.35)', shown = 1,
  } = o;
  g.save(); g.globalAlpha = a * alpha;
  // 球体
  const fg = g.createRadialGradient(cx - r * 0.35, cy - r * 0.35, r * 0.1, cx, cy, r);
  fg.addColorStop(0, 'rgba(58,120,124,0.55)');
  fg.addColorStop(0.6, fill);
  fg.addColorStop(1, 'rgba(4,10,14,0.55)');
  g.fillStyle = fg; g.beginPath(); g.arc(cx, cy, r, 0, 6.2832); g.fill();
  g.save(); g.beginPath(); g.arc(cx, cy, r, 0, 6.2832); g.clip();
  if (wire) globeGrid(g, cx, cy, r, lon0 === null ? spin * 180 / Math.PI : lon0, { col: `rgba(150,226,218,${0.26 * a})`, a });
  if (night > 0) {
    g.save(); g.translate(cx, cy); g.rotate(nightAng);
    g.fillStyle = `rgba(3,7,11,${0.80 * night})`;
    g.fillRect(0, -r, r * 1.02, r * 2);
    g.restore();
  }
  g.restore();
  // 轮廓
  ci(g, cx, cy, r, { color: col, glow, alpha: a });
  if (night > 0.2 && term) {
    g.save();
    g.beginPath(); g.arc(cx, cy, r, 0, 6.2832); g.clip();
    g.translate(cx, cy); g.rotate(nightAng);
    g.globalCompositeOperation = 'lighter';
    g.shadowColor = 'rgba(255,190,120,0.9)'; g.shadowBlur = 20;
    g.strokeStyle = 'rgba(255,214,160,0.75)'; g.lineWidth = 1.8;
    g.beginPath(); g.moveTo(0, -r); g.lineTo(0, r); g.stroke();
    g.restore();
  }
  g.restore();
}
// 木杆与日影（gnomon）
function gnomon(g, ox, groundY, h, o = {}) {
  const { f = 1, sunAng = -0.9, sunDist = 300, shadow = 1, label = true, a = 1 } = o;
  const topY = groundY - h * f;
  g.save(); g.globalAlpha = a;
  // 影
  if (shadow > 0) {
    const sx = ox + Math.tan(0.55) * h * shadow;
    g.save(); g.globalCompositeOperation = 'multiply';
    const sg = g.createLinearGradient(ox, groundY, sx, groundY);
    sg.addColorStop(0, 'rgba(14,12,10,0.75)');
    sg.addColorStop(1, 'rgba(10,9,8,0)');
    g.fillStyle = sg;
    g.beginPath();
    g.moveTo(ox - 7, groundY); g.lineTo(ox + 7, groundY);
    g.lineTo(sx + 4, groundY + 5); g.lineTo(sx - 4, groundY + 2); g.closePath(); g.fill();
    g.restore();
  }
  // 杆
  lnw(g, [[ox, groundY], [ox, topY]], { w: 3.2, color: C.amber });
  dt(g, ox, topY, 1.8, { color: '255,226,174', a });
  // 太阳与光线
  const sx2 = ox + Math.cos(sunAng) * sunDist * 0.6, sy2 = topY + Math.sin(sunAng) * sunDist * 0.6;
  dash(g, [[sx2, sy2], [ox, topY]], { color: 'rgba(255,214,150,0.45)' });
  sun(g, sx2, sy2, 16, { a: 0.9 * a });
  // 地面
  horizon(g, groundY, { w: 700, warm: 0.8, alpha: a });
  if (label) {
    const sx3 = ox + Math.tan(0.55) * h * shadow;
    dash(g, [[ox, groundY + 2], [sx3, groundY + 2]], { color: 'rgba(240,194,130,0.5)' });
    cap(g, 'SHADOW', (ox + sx3) / 2, groundY + 22, { size: 10, ls: 2.6, color: 'rgba(240,205,150,0.55)' });
  }
  g.restore();
}
// 摆钟 / 航海钟表盘
function dial(g, cx, cy, r, o = {}) {
  const { a = 1, ha = -1.9, ma = -0.4, sec = null, ticks = 60, marks = 4, lab = true, col = C.amber, sub = true, glow = 16 } = o;
  g.save(); g.globalAlpha = a;
  const face = g.createRadialGradient(cx - r * 0.3, cy - r * 0.3, 0, cx, cy, r);
  face.addColorStop(0, 'rgba(48,40,30,0.95)');
  face.addColorStop(1, 'rgba(10,10,12,0.95)');
  g.fillStyle = face; g.beginPath(); g.arc(cx, cy, r, 0, 6.2832); g.fill();
  ciw(g, cx, cy, r, { glow });
  ciw(g, cx, cy, r * 0.88, { w: 1.1, alpha: 0.6, glow: 6 });
  g.save(); g.translate(cx, cy);
  for (let i = 0; i < ticks; i++) {
    const ang = i / ticks * 6.2832 - Math.PI / 2;
    const long = i % 5 === 0;
    if (i % 15 === 0) continue;
    const r1 = r * (long ? 0.80 : 0.86), r2 = r * 0.88;
    g.strokeStyle = long ? 'rgba(240,200,140,0.75)' : 'rgba(220,196,160,0.30)';
    g.lineWidth = long ? 1.8 : 1;
    g.beginPath(); g.moveTo(Math.cos(ang) * r1, Math.sin(ang) * r1);
    g.lineTo(Math.cos(ang) * r2, Math.sin(ang) * r2); g.stroke();
  }
  for (let i = 0; i < marks; i++) {
    const ang = i / marks * 6.2832 - Math.PI / 2;
    g.save(); g.rotate(ang + Math.PI / 2);
    g.fillStyle = 'rgba(248,224,186,0.85)';
    g.fillRect(-1.5, -r * 0.90, 3, r * 0.10);
    g.restore();
  }
  if (sub) {
    g.beginPath(); g.arc(0, r * 0.38, r * 0.26, 0, 6.2832);
    g.strokeStyle = 'rgba(240,200,140,0.30)'; g.lineWidth = 1; g.stroke();
    g.strokeStyle = 'rgba(255,220,170,0.75)'; g.lineWidth = 1.4;
    g.beginPath(); g.moveTo(0, r * 0.38); g.lineTo(Math.cos(sec === null ? 1.2 : sec) * r * 0.20, r * 0.38 + Math.sin(sec === null ? 1.2 : sec) * r * 0.20); g.stroke();
  }
  // 指针
  g.globalCompositeOperation = 'lighter';
  g.shadowColor = '#ffd08a'; g.shadowBlur = 12;
  g.strokeStyle = 'rgba(255,228,182,0.95)'; g.lineCap = 'round';
  g.lineWidth = 4;
  g.beginPath(); g.moveTo(0, 0); g.lineTo(Math.cos(ha) * r * 0.55, Math.sin(ha) * r * 0.55); g.stroke();
  g.lineWidth = 2.2;
  g.beginPath(); g.moveTo(0, 0); g.lineTo(Math.cos(ma) * r * 0.78, Math.sin(ma) * r * 0.78); g.stroke();
  g.restore();
  g.fillStyle = '#ffe9c4'; g.beginPath(); g.arc(cx, cy, r * 0.045, 0, 6.2832); g.fill();
  if (lab) { cap(g, 'HARRISON  H4', cx, cy + r + 26, { size: 10, ls: 3, color: 'rgba(240,205,150,0.5)' }); }
  g.restore();
}
// 罗盘
function compass(g, cx, cy, r, o = {}) {
  const { a = 1, rot = 0, letters = true } = o;
  g.save(); g.globalAlpha = a; g.translate(cx, cy); g.rotate(rot);
  ci(g, 0, 0, r, { w: 1.6, alpha: 0.8 });
  ci(g, 0, 0, r * 0.74, { w: 1, alpha: 0.4, glow: 6 });
  for (let i = 0; i < 16; i++) {
    const ang = i / 16 * 6.2832;
    const l = i % 4 === 0 ? r * 0.16 : r * 0.08;
    g.strokeStyle = 'rgba(160,226,216,0.5)'; g.lineWidth = 1;
    g.beginPath(); g.moveTo(Math.cos(ang) * r * 0.86, Math.sin(ang) * r * 0.86);
    g.lineTo(Math.cos(ang) * (r * 0.86 + l), Math.sin(ang) * (r * 0.86 + l)); g.stroke();
  }
  // 星形指针
  g.beginPath();
  g.moveTo(0, -r * 0.78); g.lineTo(r * 0.16, 0); g.lineTo(0, r * 0.55); g.lineTo(-r * 0.16, 0); g.closePath();
  g.fillStyle = 'rgba(240,190,120,0.85)'; g.shadowColor = C.amber; g.shadowBlur = 12; g.fill();
  if (letters) {
    const S = r * 0.95;
    [[0, -S, 'N'], [S, 0, 'E'], [0, S, 'S'], [-S, 0, 'W']].forEach(([x, y, ch]) => {
      const rx = x * Math.cos(rot) - y * Math.sin(rot);
      const ry = x * Math.sin(rot) + y * Math.cos(rot);
      g.save(); g.rotate(-rot);
      g.fillStyle = 'rgba(212,240,234,0.75)'; g.font = `600 ${r * 0.16}px ${FONT_EN}`;
      g.textAlign = 'center'; g.textBaseline = 'middle';
      g.fillText(ch, rx, ry);
      g.restore();
    });
  }
  g.restore();
}
// 船
function ship(g, x, y, s = 1, o = {}) {
  const { a = 1, rot = 0, col = C.cyanHi } = o;
  g.save(); g.globalAlpha = a; g.translate(x, y); g.rotate(rot); g.scale(s, s);
  g.strokeStyle = col; g.lineWidth = 1.6; g.shadowColor = C.cyan; g.shadowBlur = 10;
  g.beginPath(); g.moveTo(-34, 0); g.lineTo(30, 0); g.lineTo(22, 12); g.lineTo(-26, 12); g.closePath(); g.stroke();
  g.beginPath(); g.moveTo(-2, 0); g.lineTo(-2, -46); g.stroke();
  g.beginPath(); g.moveTo(-2, -44); g.lineTo(26, -10); g.lineTo(-2, -8); g.closePath();
  g.fillStyle = 'rgba(140,224,214,0.22)'; g.fill();
  g.beginPath(); g.moveTo(-2, -40); g.lineTo(-26, -12); g.lineTo(-2, -10); g.closePath(); g.fill();
  g.restore();
}
// 小人（剪影 + 影）
function fig(g, x, y, h = 80, o = {}) {
  const { a = 1, darker = false, shadow = 1 } = o;
  g.save(); g.globalAlpha = a;
  const col = darker ? 'rgba(8,12,16,0.92)' : 'rgba(240,236,222,0.92)';
  g.fillStyle = col;
  g.beginPath(); g.arc(x, y - h * 0.86, h * 0.075, 0, 6.2832); g.fill();
  g.strokeStyle = col; g.lineWidth = Math.max(2, h * 0.045); g.lineCap = 'round';
  g.beginPath(); g.moveTo(x, y - h * 0.78); g.lineTo(x, y - h * 0.36); g.stroke();
  g.beginPath(); g.moveTo(x, y - h * 0.62); g.lineTo(x - h * 0.13, y - h * 0.46); g.stroke();
  g.beginPath(); g.moveTo(x, y - h * 0.62); g.lineTo(x + h * 0.13, y - h * 0.46); g.stroke();
  g.beginPath(); g.moveTo(x, y - h * 0.36); g.lineTo(x - h * 0.09, y); g.stroke();
  g.beginPath(); g.moveTo(x, y - h * 0.36); g.lineTo(x + h * 0.09, y); g.stroke();
  if (shadow) {
    g.strokeStyle = 'rgba(10,14,18,0.55)'; g.lineWidth = Math.max(1.5, h * 0.03);
    g.beginPath(); g.moveTo(x, y); g.lineTo(x + h * 0.55, y + h * 0.12); g.stroke();
  }
  g.restore();
}
// 海岸线（分形）
function coastPts(w, amp, seed, off = 0) {
  const r = mulberry(seed);
  const ph = [r() * 6.28, r() * 6.28, r() * 6.28, r() * 6.28];
  const pts = [];
  for (let i = 0; i <= 90; i++) {
    const x = -w / 2 + (w * i) / 90;
    const u = x / w;
    let y = amp * (0.55 * Math.sin(u * 7.1 + ph[0]) + 0.30 * Math.sin(u * 17.3 + ph[1])
      + 0.16 * Math.sin(u * 41 + ph[2]) + 0.09 * Math.sin(u * 83 + ph[3]));
    y += amp * 0.10 * Math.sin(i * 1.7 + seed);
    pts.push([x, y + off]);
  }
  return pts;
}
function coast(g, x, y, w, amp, seed, o = {}) {
  const { f = 1, a = 1, col = C.cyanHi, wl = 2.2, glow = 16, fillBelow = 0, dy = 0 } = o;
  const pts = coastPts(w, amp, seed, 0).map(p => [p[0] + x, p[1] + y]);
  const n = Math.max(2, Math.floor(pts.length * clamp(f)));
  const seg = pts.slice(0, n);
  if (fillBelow) {
    g.save(); g.globalAlpha = a * fillBelow;
    g.beginPath(); g.moveTo(seg[0][0], seg[0][1]);
    seg.forEach(p => g.lineTo(p[0], p[1]));
    g.lineTo(seg[seg.length - 1][0], y + dy + 400); g.lineTo(seg[0][0], y + dy + 400); g.closePath();
    const gr = g.createLinearGradient(0, y - 60, 0, y + 200);
    gr.addColorStop(0, 'rgba(38,96,102,0.55)');
    gr.addColorStop(1, 'rgba(6,14,20,0.05)');
    g.fillStyle = gr; g.fill();
    g.restore();
  }
  if (glow > 0) glowLine(g, seg, { w: wl, color: col, glow, alpha: a });
  else {
    g.save(); g.globalAlpha = a; g.strokeStyle = col; g.lineWidth = wl; g.lineJoin = 'round';
    g.beginPath(); seg.forEach((p, i) => i ? g.lineTo(p[0], p[1]) : g.moveTo(p[0], p[1])); g.stroke();
    g.restore();
  }
  return pts;
}
// 岛
function island(g, cx, cy, rx, ry, seed, o = {}) {
  const { a = 1, f = 1, ring = 0.6 } = o;
  const r = mulberry(seed);
  const pts = [];
  const n = 26;
  for (let i = 0; i < n; i++) {
    const ang = i / n * 6.2832;
    const k = 0.72 + r() * 0.42;
    pts.push([cx + Math.cos(ang) * rx * k, cy + Math.sin(ang) * ry * k]);
  }
  const seg = pts.slice(0, Math.max(3, Math.floor(n * clamp(f))));
  g.save(); g.globalAlpha = a;
  g.beginPath(); seg.forEach((p, i) => i ? g.lineTo(p[0], p[1]) : g.moveTo(p[0], p[1]));
  g.fillStyle = 'rgba(22,52,54,0.55)'; g.fill();
  g.restore();
  if (seg.length > 2) glowLine(g, seg, { w: 2, color: C.cyan, glow: 14, alpha: a });
  if (ring) glowCircle(g, cx, cy, Math.max(rx, ry) * 1.35, { w: 1, color: C.cyanDim, glow: 6, alpha: a * ring * 0.6, dash: [3, 6] });
  return pts;
}
// 火山
function volcano(g, cx, baseY, w, h, o = {}) {
  const { a = 1, f = 1, erupt = 0, lava = 0, t = 0 } = o;
  g.save(); g.globalAlpha = a;
  const hh = h * f;
  g.beginPath();
  g.moveTo(cx - w / 2, baseY); g.lineTo(cx - w * 0.10, baseY - hh); g.lineTo(cx + w * 0.10, baseY - hh);
  g.lineTo(cx + w / 2, baseY); g.closePath();
  const fg = g.createLinearGradient(0, baseY - hh, 0, baseY);
  fg.addColorStop(0, 'rgba(40,34,30,0.95)');
  fg.addColorStop(1, 'rgba(8,10,12,0.95)');
  g.fillStyle = fg; g.fill();
  g.strokeStyle = 'rgba(240,190,130,0.55)'; g.lineWidth = 1.6; g.stroke();
  // 火山口
  g.beginPath(); g.moveTo(cx - w * 0.10, baseY - hh);
  g.quadraticCurveTo(cx, baseY - hh + 8, cx + w * 0.10, baseY - hh); g.stroke();
  if (lava > 0) {
    g.save(); g.globalCompositeOperation = 'lighter';
    g.strokeStyle = 'rgba(255,150,70,0.85)'; g.lineWidth = 3; g.shadowColor = '#ff8a3a'; g.shadowBlur = 16;
    g.beginPath(); g.moveTo(cx - w * 0.01, baseY - hh + 4);
    g.quadraticCurveTo(cx + w * 0.06, baseY - hh * 0.55, cx + w * 0.20, baseY);
    g.stroke();
    g.restore();
  }
  if (erupt > 0) {
    g.save(); g.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 18; i++) {
      const u = i / 18;
      const px = cx + Math.sin(i * 2.4 + t * 1.6) * w * 0.20 * u * 1.6;
      const py = baseY - hh - u * h * 0.9;
      dt(g, px, py, 1.1 + (1 - u) * 2.2, { a: erupt * (1 - u * 0.5) * 0.8, color: '255,168,96' });
    }
    softGlow(g, cx, baseY - hh - 10, w * 0.9, '255,150,80', 0.20 * erupt);
    g.restore();
  }
  g.restore();
}
// 山脊剖面
function profile(g, cx, baseY, w, h, ptsN, seed, o = {}) {
  const { f = 1, a = 1, col = C.ivory, fill = 0.35, wl = 2 } = o;
  const r = mulberry(seed);
  const raw = [];
  for (let i = 0; i <= ptsN; i++) {
    const u = i / ptsN;
    const peak = Math.sin(u * Math.PI) * 0.75 + 0.25;
    raw.push(0.35 + 0.65 * peak * (0.55 + 0.45 * Math.sin(u * 9.7 + r() * 3)));
  }
  const pts = raw.map((v, i) => [cx - w / 2 + w * i / ptsN, baseY - h * clamp(v)]);
  const n = Math.max(2, Math.floor(pts.length * clamp(f)));
  const seg = pts.slice(0, n);
  if (fill > 0) {
    g.save(); g.globalAlpha = a;
    g.beginPath(); g.moveTo(seg[0][0], baseY + 60);
    seg.forEach(p => g.lineTo(p[0], p[1]));
    g.lineTo(seg[seg.length - 1][0], baseY + 60); g.closePath();
    const fg = g.createLinearGradient(0, baseY - h, 0, baseY + 40);
    fg.addColorStop(0, 'rgba(120,196,190,0.30)');
    fg.addColorStop(1, 'rgba(8,16,20,0.02)');
    g.fillStyle = fg; g.fill();
    g.restore();
  }
  glowLine(g, seg, { w: wl, color: col, glow: 12, alpha: a });
  return pts;
}
// 月面
function moon(g, cx, cy, r, o = {}) {
  const { a = 1, shadow = 0, craters = true, arc = true } = o;
  g.save(); g.globalAlpha = a;
  const fg = g.createRadialGradient(cx - r * 0.3, cy - r * 0.35, r * 0.1, cx, cy, r);
  fg.addColorStop(0, 'rgba(246,240,224,0.98)');
  fg.addColorStop(0.7, 'rgba(212,204,186,0.94)');
  fg.addColorStop(1, 'rgba(150,146,134,0.9)');
  g.fillStyle = fg; g.beginPath(); g.arc(cx, cy, r, 0, 6.2832); g.fill();
  if (craters) {
    const rr = mulberry(77);
    g.fillStyle = 'rgba(120,116,106,0.28)';
    for (let i = 0; i < 12; i++) {
      const ang = rr() * 6.2832, d = Math.sqrt(rr()) * r * 0.78;
      g.beginPath(); g.arc(cx + Math.cos(ang) * d, cy + Math.sin(ang) * d, r * (0.04 + rr() * 0.09), 0, 6.2832); g.fill();
    }
  }
  if (shadow > 0) {
    g.save(); g.beginPath(); g.arc(cx, cy, r, 0, 6.2832); g.clip();
    g.fillStyle = `rgba(190,80,56,${0.55 * shadow})`;
    g.beginPath(); g.arc(cx + r * 0.75, cy + r * 0.12, r * 1.02, 0, 6.2832); g.fill();
    g.fillStyle = `rgba(150,52,38,${0.35 * shadow})`;
    g.beginPath(); g.arc(cx + r * 0.95, cy + r * 0.10, r * 1.02, 0, 6.2832); g.fill();
    g.restore();
    if (arc) ar(g, cx + r * 0.75, cy + r * 0.12, r * 1.02, Math.PI * 0.98, Math.PI * 1.55, { color: 'rgba(255,170,120,0.75)', glow: 18, w: 1.8 });
  }
  glowCircle(g, cx, cy, r, { w: 1.2, color: 'rgba(246,240,224,0.75)', glow: 10, alpha: a * 0.8 });
  g.restore();
}
// 纸
function paper(g, cx, cy, w, h, rot, o = {}) {
  const { a = 1, fill = 'rgba(186,174,152,0.93)', line = 'rgba(90,80,62,0.55)', ruled = 0, grid = 0 } = o;
  g.save(); g.globalAlpha = a; g.translate(cx, cy); g.rotate(rot || 0);
  g.fillStyle = fill; g.fillRect(-w / 2, -h / 2, w, h);
  g.strokeStyle = line; g.lineWidth = 1.4; g.strokeRect(-w / 2, -h / 2, w, h);
  g.save(); g.beginPath(); g.rect(-w / 2, -h / 2, w, h); g.clip();
  if (ruled) {
    g.strokeStyle = 'rgba(90,80,62,0.16)'; g.lineWidth = 1;
    for (let y = -h / 2 + 24; y < h / 2; y += 24) { g.beginPath(); g.moveTo(-w / 2, y); g.lineTo(w / 2, y); g.stroke(); }
  }
  if (grid) {
    g.strokeStyle = 'rgba(90,80,62,0.20)'; g.lineWidth = 1;
    for (let x = -w / 2; x < w / 2; x += grid) { g.beginPath(); g.moveTo(x, -h / 2); g.lineTo(x, h / 2); g.stroke(); }
    for (let y = -h / 2; y < h / 2; y += grid) { g.beginPath(); g.moveTo(-w / 2, y); g.lineTo(w / 2, y); g.stroke(); }
  }
  g.restore();
  // 角落折痕
  g.strokeStyle = 'rgba(120,108,88,0.35)'; g.lineWidth = 1;
  g.beginPath(); g.moveTo(w / 2 - 26, -h / 2); g.lineTo(w / 2, -h / 2 + 26); g.stroke();
  g.restore();
}
// 尺子
function ruler(g, x, y, len, o = {}) {
  const { a = 1, rot = 0, vertical = false, ticks = 10, col = C.amber, label = true } = o;
  g.save(); g.globalAlpha = a; g.translate(x, y); g.rotate(rot);
  if (vertical) g.rotate(Math.PI / 2);
  g.strokeStyle = col; g.lineWidth = 1.6; g.shadowColor = col; g.shadowBlur = 8;
  g.strokeRect(0, -8, len, 16);
  for (let i = 0; i <= ticks; i++) {
    const xx = (len * i) / ticks, big = i % 5 === 0;
    g.beginPath(); g.moveTo(xx, big ? -8 : -4); g.lineTo(xx, 8); g.stroke();
    if (label && big && i < ticks) {
      g.save(); g.rotate(0);
      g.fillStyle = 'rgba(250,228,190,0.8)'; g.font = '600 11px ' + FONT_EN;
      g.textAlign = 'center'; g.fillText(String(i * 2), xx, 24);
      g.restore();
    }
  }
  g.restore();
}
// 标注牌
function tag(g, x, y, cnTxt, enTxt, o = {}) {
  const { a = 1, w = 0, h = 44, side = 'l', col = 'rgba(240,200,140,0.5)' } = o;
  const ww = w || (enTxt ? enTxt.length * 7.2 + 28 : 90);
  g.save(); g.globalAlpha = a;
  const x0 = side === 'r' ? x - ww : x;
  g.fillStyle = 'rgba(8,14,18,0.55)'; g.fillRect(x0, y, ww, h);
  g.strokeStyle = col; g.lineWidth = 1.2;
  g.beginPath(); g.moveTo(x0, y); g.lineTo(x0 + ww, y); g.moveTo(x0, y + h); g.lineTo(x0 + ww, y + h); g.stroke();
  cnT(g, cnTxt, x0 + 12, y + 17, 16, { align: 'left', glow: 8 });
  if (enTxt) cap(g, enTxt, x0 + 12, y + 33, { size: 9, ls: 2.2, color: 'rgba(200,226,220,0.55)' });
  g.restore();
  return ww;
}
// 一列刻度（经纬度）
function degTicks(g, x, y, w, n, o = {}) {
  const { a = 1, label = true, col = 'rgba(150,220,214,0.45)' } = o;
  g.save(); g.globalAlpha = a; g.strokeStyle = col; g.lineWidth = 1;
  for (let i = 0; i <= n; i++) {
    const xx = x + (w * i) / n;
    g.beginPath(); g.moveTo(xx, y); g.lineTo(xx, y + (i % 5 === 0 ? 7 : 3)); g.stroke();
    if (label && i % 5 === 0) {
      g.fillStyle = 'rgba(180,226,220,0.5)'; g.font = `500 11px ${FONT_EN}`;
      g.textAlign = 'center'; g.fillText(`${i * 10}°`, xx, y - 8);
    }
  }
  g.restore();
}

