  glowLine(g, seg, { w: 2.6, color: C.amberHi, glow: 22 });
  cap(g, 'SONAR  ·  1957', -520, 268, { size: 10, ls: 2.8, align: 'left', color: 'rgba(200,230,224,0.4)' });
  cap(g, 'MID-OCEAN RIDGE', 0, 268, { size: 10, ls: 2.6, color: 'rgba(240,205,150,0.55)' });
