/* ---------- 31 · 贯穿全世界最长的山脉
 * 洋中脊是连续的海底山脉系统，全长约 65,000 km（地球上最长的一条山脉）。
 * 折线是粗化的脊线走向：大西洋中脊 → 印度洋中脊 → 东太平洋海隆，经正射投影上球。
 */
const RIDGE = [[65,-17],[55,-32],[45,-28],[33,-40],[20,-45],[8,-33],[-5,-15],[-20,-12],[-35,-15],
[-50,-5],[-52,15],[-45,30],[-30,30],[-15,45],[0,58],[10,62],[5,72],[-10,70],[-25,70],[-40,80],
[-50,100],[-45,120],[-35,135],[-25,150],[-15,165],[0,178],[10,-170],[20,-155],[30,-142],[40,-130],
[50,-135],[55,-150],[58,-162]];
ART[31] = (g, e, T, t) => {
  stage(g, {});
  const cx = 0, cy = -16, R = 200, lon0 = 20;
  globe(g, cx, cy, R, { a: E(e, 0, 0.9), wire: true, night: 0, lon0 });
  drawGlobeLands(g, cx, cy, R, lon0, { a: 0.8 });
  const f = E(e, 0.3, 2.3);
  for (const s of clipLineLL(RIDGE, lon0, 0)) {
    if (f <= s.f0) continue;
    const k = clamp((f - s.f0) / Math.max(0.001, s.f1 - s.f0));
    const pts = partial(s.pts.map(p => [cx + p[0] * R, cy + p[1] * R]), k);
    if (pts.length > 1) glowLine(g, pts, { w: 2.8, color: C.amberHi, glow: 20 });
  }
  num(g, '65 000 km', 0, 220, 32, { a: E(e, 1.4, 1.0) });
  cap(g, 'THE LONGEST CHAIN ON EARTH', 0, 254, { size: 10, ls: 2.8, color: 'rgba(200,230,224,0.45)' });
  cap(g, 'MID-OCEAN RIDGE · 脊顶高出深海平原约 2.5 km', 0, -266, { size: 10, ls: 2.6, color: 'rgba(240,205,150,0.5)' });
};

