/* ---------- 45 · 而月亮上那道圆圆的暗弧
 * 月球轨道处的本影直径约 9,200 km，是月球直径（3,475 km）的 2.6 倍，
 * 所以月面上那道暗弧的半径是月球的 2.6 倍——弧很缓，不是跟月亮一样大的圆。
 */
ART[45] = (g, e, T, t) => {
  stage(g, {});
  const mx = 20, my = -6, mr = 150;
  moon(g, mx, my, mr, { a: E(e, 0, 1.0), shadow: 0, craters: true, arc: false });
  const sf = 0.30 + 0.40 * E(e, 0.6, 2.2);
  const ur = mr * 2.6, d = ur * (2.4 - 2.4 * sf);
  g.save(); g.globalAlpha = 0.9 * sf;
  g.beginPath(); g.arc(mx, my, mr, 0, 6.2832); g.clip();
  const sg = g.createRadialGradient(mx + d, my, mr * 0.2, mx + d, my, ur);
  sg.addColorStop(0, 'rgba(150,52,36,0.72)'); sg.addColorStop(1, 'rgba(120,44,32,0.55)');
  g.fillStyle = sg;
  g.beginPath(); g.arc(mx + d, my, ur, 0, 6.2832); g.fill();
  g.restore();
  ar(g, mx + d, my, ur, Math.PI * 0.55, Math.PI * 1.45, { color: 'rgba(255,168,120,0.95)', w: 3, glow: 26, a: sf });
  cap(g, '月球轨道处本影直径 ≈ 9 200 km = 2.6 个月球', 0, 214, { size: 10, ls: 1.8, color: 'rgba(240,200,170,0.6)' });
  cap(g, "EARTH'S UMBRA ON THE MOON", 0, 240, { size: 9.5, ls: 2.4, color: 'rgba(240,200,170,0.4)' });
};

