  g.beginPath(); g.arc(0, cy, R, Math.PI, 0); g.closePath();
  const eg = g.createLinearGradient(0, cy - R, 0, cy + 20);
  eg.addColorStop(0, 'rgba(46,96,102,0.85)');
  eg.addColorStop(0.35, 'rgba(20,48,54,0.85)');
  eg.addColorStop(1, 'rgba(8,14,20,0.9)');
