  g.restore();
  ar(g, 0, cy, R, Math.PI * 1.03, Math.PI * 1.97, { w: 2.6, color: C.cyanHi, glow: 22 });
  // 地球的经纬
  g.save(); g.globalAlpha = 0.35;
